# qx2_clz :: 1
def qx2_clz(n):
    if n == 0:
        return 32
    c = 0
    while not (n & (1 << 31)):
        n <<= 1
        c += 1
    return c

if __name__ == '__main__':
    print(qx2_clz(1))

